9	// Simple rolling mean over a flat array.  Returns a vector of the same length;
10	// the first (window-1) positions are NaN (not enough data yet).
11	std::vector<double> rolling_mean(const std::vector<double>& values, int window) {
12	    if (window <= 0) throw std::invalid_argument("window must be positive");
13	    const std::size_t n = values.size();
14	    std::vector<double> out(n, std::numeric_limits<double>::quiet_NaN());
15	    double sum = 0.0;
16	    for (std::size_t i = 0; i < n; ++i) {
17	        sum += values[i];
18	        if (i >= static_cast<std::size_t>(window)) sum -= values[i - window];
19	        if (i + 1 >= static_cast<std::size_t>(window)) {
20	            out[i] = sum / window;
21	        }
22	    }
23	    return out;
24	}
