26	PYBIND11_MODULE(oil_volume_cpp, m) {
27	    m.doc() = "C++ core for oil-volume metrics (pybind11 bridge)";
28	    m.def(
29	        "rolling_mean",
30	        &rolling_mean,
31	        py::arg("values"),
32	        py::arg("window"),
33	        "Compute a rolling arithmetic mean over *values* with the given *window*.\n"
34	        "Returns a list of length len(values); the first window-1 entries are NaN."
35	    );
36	}
